const question = $fromAI('question', 'The user question to analyze', 'string');

// Analyze question for filters
const lowerQ = question.toLowerCase();
const result = {
  query: question,
  top_k: 7,
  filters: {}
};

// Detect date-related queries
if (lowerQ.includes('najnowsze') || lowerQ.includes('ostatnie') || lowerQ.includes('nowe') || lowerQ.includes('trendy')) {
  const currentDate = new Date();
  const sixMonthsAgo = new Date();
  sixMonthsAgo.setMonth(currentDate.getMonth() - 6);
  result.filters.date_range = {
    start: sixMonthsAgo.toISOString().split('T')[0],
    end: currentDate.toISOString().split('T')[0]
  };
  result.top_k = 10;
}

// Detect tags
const tagKeywords = {
  'ai': ['ai', 'sztuczna inteligencja', 'machine learning', 'llm', 'agent'],
  'product management': ['product management', 'produkt', 'pm'],
  'design': ['design', 'ux', 'ui', 'projektowanie'],
  'development': ['development', 'programowanie', 'kod', 'developer']
};

const detectedTags = [];
for (const [tag, keywords] of Object.entries(tagKeywords)) {
  if (keywords.some(kw => lowerQ.includes(kw))) {
    detectedTags.push(tag);
  }
}
if (detectedTags.length > 0) {
  result.filters.tags = detectedTags;
}

// Detect section type needs
if (lowerQ.includes('checklist') || lowerQ.includes('lista') || lowerQ.includes('kroki')) {
  result.filters.section_type = ['checklist'];
  result.top_k = 5;
} else if (lowerQ.includes('tldr') || lowerQ.includes('podsumowanie') || lowerQ.includes('skrót')) {
  result.filters.section_type = ['tldr'];
  result.top_k = 5;
} else if (lowerQ.includes('insight') || lowerQ.includes('kluczowe')) {
  result.filters.section_type = ['key_insight'];
} else if (lowerQ.includes('szczegół') || lowerQ.includes('jak')) {
  result.filters.section_type = ['content', 'key_insight'];
  result.top_k = 10;
}

// Detect categories
if (lowerQ.includes('produkt')) result.filters.categories = ['Produkt'];
if (lowerQ.includes('design')) result.filters.categories = ['Design'];

return JSON.stringify(result, null, 2);

