// Format RAG search results into readable context
const results = $input.item.json;

if (!results || !Array.isArray(results) || results.length === 0) {
  return {
    json: {
      context: 'Brak wyników wyszukiwania. System RAG nie znalazł odpowiednich artykułów.',
      hasResults: false,
      resultCount: 0
    }
  };
}

// Build formatted context
let context = `Znaleziono ${results.length} wyników z bazy wiedzy:\n\n`;

results.forEach((result, index) => {
  context += `--- Wynik ${index + 1} (Score: ${(result.score * 100).toFixed(1)}%) ---\n`;
  context += `Tytuł: ${result.title}\n`;
  context += `URL: ${result.url}\n`;
  context += `Typ sekcji: ${result.section_type}\n`;

  if (result.publication_date) {
    context += `Data publikacji: ${result.publication_date}\n`;
  }

  if (result.tags && result.tags.length > 0) {
    context += `Tagi: ${result.tags.join(', ')}\n`;
  }

  if (result.categories && result.categories.length > 0) {
    context += `Kategorie: ${result.categories.join(', ')}\n`;
  }

  context += `\nTreść:\n${result.text}\n\n`;
});

return {
  json: {
    context,
    hasResults: true,
    resultCount: results.length,
    results,
    originalQuestion: $('Webhook: RAG Question').item.json.body.question
  }
};
